class InventoryForm:
    def __init__(self) -> None:
        self.doc = fitz.open()
        self.page = self.doc.new_page(width=A4_WIDTH, height=A4_HEIGHT)
        self.scale = min((A4_WIDTH - 2 * SIDE_MARGIN) / ARTWORK.width,
                         (A4_HEIGHT - 2 * VERTICAL_MARGIN) / ARTWORK.height)
        offset_x = (A4_WIDTH - ARTWORK.width * self.scale) / 2 - ARTWORK.x0 * self.scale
        offset_y = (A4_HEIGHT - ARTWORK.height * self.scale) / 2 - ARTWORK.y0 * self.scale
        self.layout = fitz.Matrix(self.scale, 0, 0, self.scale, offset_x, offset_y)

    def line(self, x1: float, y1: float, x2: float, y2: float,
             width: float = 0.35) -> None:
        self.page.draw_line(fitz.Point(x1, y1) * self.layout,
                            fitz.Point(x2, y2) * self.layout,
                            color=BLACK, width=width * self.scale)

    def text(self, x: float, y: float, value: str, size: float = 12) -> None:
        self.page.insert_text(fitz.Point(x, y) * self.layout, value,
                              fontname="tibo", fontsize=size * self.scale, color=BLACK)

    def center(self, x: float, y: float, value: str, size: float = 12) -> None:
        self.text(x - LABEL_FONT.text_length(value, fontsize=size) / 2, y, value, size)

    def field(self, name: str, label: str, x1: float, x2: float,
              baseline: float, *, centered: bool = False) -> None:
        self.line(x1, baseline, x2, baseline)
        widget = fitz.Widget()
        widget.field_name = name
        widget.field_label = label
        widget.field_type = fitz.PDF_WIDGET_TYPE_TEXT
        widget.rect = fitz.Rect(x1 if centered else x1 + 1.5,
                                baseline - 14, x2, baseline - 0.3) * self.layout
        widget.text_font = "Helv"
        widget.text_fontsize = 9 * self.scale
        widget.text_color = BLACK
        widget.border_width = 0
        added = self.page.add_widget(widget)
        if centered:
            self.doc.xref_set_key(added.xref, "Q", "1")

    def figure(self) -> None:
        """Place the reference-traced SVG in the sheet as vector PDF artwork."""
        with fitz.open(stream=INVENTORY_CHARACTER_SVG.encode("utf-8"), filetype="svg") as svg:
            with fitz.open(stream=svg.convert_to_pdf(), filetype="pdf") as artwork:
                # Crop the scan's surrounding whitespace while keeping the
                # original figure's proportions and all finger/toe details.
                self.page.show_pdf_page(
                    fitz.Rect(410, 65, 494, 221) * self.layout,
                    artwork,
                    clip=fitz.Rect(92, 70, 586, 1018),
                )

    def build(self) -> None:
        self.center(288, 32, "RAHA- JA VARUSTELOMAKE", size=12)
        for coords in [
            (47, 43, 529, 43), (47, 43, 47, 739),
            (529, 43, 529, 739), (47, 739, 529, 739),
            (214, 43, 214, 232), (47, 232, 529, 232),
        ]:
            self.line(*coords, width=1.1)

        self.text(51, 60, "RAHAT:")
        for name, label, y in [
            ("mithrilrahoja", "Mithrilrahoja:", 79),
            ("kultarahoja", "Kultarahoja:", 98),
            ("hopearahoja", "Hopearahoja:", 117),
            ("pronssirahoja", "Pronssirahoja:", 151),
            ("kuparikolikoita", "Kuparikolikoita:", 170),
            ("tinakolikoita", "Tinakolikoita:", 189),
            ("rautakolikoita", "Rautakolikoita:", 208),
            ("jalokivia", "JALOKIVIÄ:", 227),
        ]:
            self.text(51, y, label)
            self.field(name, label.rstrip(":"), 150, 195, y + 2, centered=True)

        self.text(218, 62, "KOKO- JA PAIKKAKAAVIO:")
        self.text(218, 81, "Keskiruumiin koko:")
        self.field("keskiruumiin_koko", "Keskiruumiin koko", 326, 359, 84, centered=True)
        self.text(218, 100, "Pään koko:")
        self.field("paan_koko", "Pään koko", 326, 359, 103, centered=True)
        self.text(218, 119, "Käsien/jalkojen")
        self.text(218, 134, "koko:")
        self.field("kasien_jalkojen_koko", "Käsien/jalkojen koko", 326, 359, 122,
                   centered=True)
        self.figure()

        self.text(51, 249, "VARUSTEET, MATKATAVARAT JA YRTIT:")
        self.center(72, 266, "Paino")
        self.center(156, 266, "Paikka")
        self.text(215, 266, "Kuvaus")
        for row in range(ROWS):
            y = 285 + row * 18.5
            for name, label, x1, x2 in [
                ("paino", "Paino", 51, 91),
                ("paikka", "Paikka", 106, 200),
                ("kuvaus", "Kuvaus", 215, 519),
            ]:
                self.field(f"varuste_{row+1:02}_{name}", f"Varuste {row+1}: {label}",
                           x1, x2, y, centered=name == "paino")

        self.doc.set_metadata({
            "title": "Raha- ja varustelomake – täytettävä",
            "subject": "Finnish Rolemaster inventory sheet with AcroForm fields",
            "creator": "inventorysheet.py / PyMuPDF",
        })
        self.doc.xref_set_key(self.page.xref, "Tabs", "/R")
        self.doc.need_appearances(False)


def verify(path: Path) -> int:
    """Check field geometry and save/reopen representative Finnish values."""
    with fitz.open(path) as doc:
        assert len(doc) == 1
        page = doc[0]
        assert abs(page.rect.width - A4_WIDTH) < 0.01
        assert abs(page.rect.height - A4_HEIGHT) < 0.01
        printable = fitz.Rect(SIDE_MARGIN - 0.01, VERTICAL_MARGIN - 0.01,
                              A4_WIDTH - SIDE_MARGIN + 0.01,
                              A4_HEIGHT - VERTICAL_MARGIN + 0.01)
        for drawing in page.get_drawings():
            rect = drawing["rect"]
            half_stroke = (drawing.get("width") or 0) / 2
            painted = fitz.Rect(rect.x0 - half_stroke, rect.y0 - half_stroke,
                                rect.x1 + half_stroke, rect.y1 + half_stroke)
            assert printable.contains(painted), "Artwork exceeds A4 print margins"
        assert not page.get_images(), "Sheet must remain vector artwork"
        assert "JALOKIVIÄ:" in page.get_text()
        widgets = list(page.widgets())
        assert len(widgets) == 11 + ROWS * 3
        assert len({w.field_name for w in widgets}) == len(widgets)
        labels = [
            span
            for block in page.get_text("dict")["blocks"] if "lines" in block
            for line in block["lines"]
            for span in line["spans"]
        ]
        for widget in widgets:
            assert widget.field_type == fitz.PDF_WIDGET_TYPE_TEXT
            assert printable.contains(widget.rect) and not widget.rect.is_empty
            for label in labels:
                assert (widget.rect & fitz.Rect(label["bbox"])).get_area() < 0.1, (
                    f"Field {widget.field_name} overlaps {label['text']!r}"
                )
        for label in labels:
            assert printable.contains(fitz.Rect(label["bbox"])), "Label exceeds print margins"
        for index, widget in enumerate(widgets):
            for other in widgets[index + 1:]:
                assert (widget.rect & other.rect).get_area() < 0.1
        samples = {
            "mithrilrahoja": "12",
            "jalokivia": "3",
            "keskiruumiin_koko": "M",
            "paan_koko": "58",
            "kasien_jalkojen_koko": "42",
            "varuste_01_paino": "2,5",
            "varuste_01_paikka": "Vyöllä",
            "varuste_01_kuvaus": "Teräsmiekka",
            "varuste_25_kuvaus": "Yrttejä ja köyttä",
        }
        for widget in widgets:
            if widget.field_name in samples:
                widget.field_value = samples[widget.field_name]
                widget.update()
        with fitz.open(stream=doc.tobytes(), filetype="pdf") as filled:
            values = {w.field_name: w.field_value for w in filled[0].widgets()}
            assert all(values[name] == value for name, value in samples.items())
            filled[0].get_pixmap()
        return len(widgets)


def main(
    output: Path = typer.Option(ROOT / "varustelomake.pdf", help="Destination PDF file."),
    preview: Path | None = typer.Option(None, help="Optional destination PNG preview."),
) -> None:
    output = output.expanduser().resolve()
    preview = preview.expanduser().resolve() if preview else None
    if output.suffix.lower() != ".pdf" or preview and preview.suffix.lower() != ".png":
        logger.error("Use .pdf for the output and .png for the preview")
        raise typer.Exit(code=1)
    try:
        form = InventoryForm()
        try:
            form.build()
            form.doc.save(output, garbage=4, deflate=True)
            if preview:
                form.page.get_pixmap(matrix=fitz.Matrix(2, 2)).save(preview)
        finally:
            form.doc.close()
        fields = verify(output)
    except (OSError, RuntimeError, ValueError, AssertionError) as exc:
        logger.error("Could not create inventory sheet: {}", exc)
        raise typer.Exit(code=1) from exc
    logger.info("Wrote {} — {} text fields; validation passed", output, fields)


if __name__ == "__main__":
    typer.run(main)
